346	        // 只创建了一条申请
347	        JsonNode history = getOk("/api/windows/" + windowId + "/history");
348	        assertEquals(1, history.get("allocations").size());
349	        // 批准命令重放
350	        String approveKey = key("ap");
351	        JsonNode approved = postOk("/api/allocations/" + allocationKey + "/approve",
352	                Map.of("commandKey", approveKey), null);
353	        JsonNode approvedReplay = postOk("/api/allocations/" + allocationKey + "/approve",
354	                Map.of("commandKey", approveKey), null);
355	        assertEquals(approved, approvedReplay);
356	        assertEquals("1.5", capacity(windowId).get("approvedTotal").asText());
357	    }
