            requireKey("settlementKey", item.settlementKey());
            requireKey("allocationKey", item.allocationKey());
            LocalDate date = parseDate("date", item.date());
            BigDecimal delivered = parseAmount("deliveredAmount", item.deliveredAmount());
            if (!seenKeys.add(item.settlementKey())) throw badRequest("INVALID_ARGUMENT", "批内 settlementKey 重复: " + key);
            parsed.add(new Parsed(...));
        }
        String params = build...
        return runCommand("SETTLEMENT_BATCH", commandKey, params, SettlementBatchResponse.class, () -> {
            // 业务键复用检查（换 commandKey 复用 -> 409）
            for (Parsed p : parsed) {
                if (repository.findSettlementByKey(p.settlementKey()) != null) {
                    throw ApiException.conflict("SETTLEMENT_KEY_REUSED", "settlementKey 已被使用: " + p.settlementKey());
                }
            }
            // 解析申请与窗口（不可变，无需锁定）
            Map<String, AllocationRow> allocations = new LinkedHashMap<>();
            Map<String, WindowRow> windows = new LinkedHashMap<>();
            for (Parsed p : parsed) {
                AllocationRow a = allocations.get(p.allocationKey());
                if (a == null) {
                    a = repository.findAllocationByKey(p.allocationKey());
                    if (a == null) throw notFound ALLOCATION_NOT_FOUND;
                    allocations.put(...);
                    WindowRow w = repository.findWindowById(a.windowId());
                    windows.put(p.allocationKey(), w);
                }
            }
            // 按固定顺序锁定蒸发率行（渠道+日期升序），与“修改率”按提交顺序串行裁决
            Map<String, EvaporationRateRow> rates = new LinkedHashMap<>();
            List<String[]> rateKeys = ...sorted distinct (channel, date)
            for each: EvaporationRateRow rate = repository.lockRate(channel, date);
                if (rate == null) throw unprocessable RATE_MISSING ...
            // 按固定顺序锁定申请行（业务键升序），得到最新持有额度，防止并发超卖
            Map<String, AllocationRow> locked = new LinkedHashMap<>();
            for key in sorted alloc keys: locked.put(key, repository.lockAllocationByKey(key));
            // 完整预校验：状态、窗口日期、逐笔舍入守恒、完整最终余额
            Map<String, BigDecimal> running = new LinkedHashMap<>();
            locked.forEach((k, a) -> running.put(k, a.heldAmount()));
            List<Computed> computed = new ArrayList<>();
            for (Parsed p : parsed) {
                AllocationRow a = locked.get(p.allocationKey());
                if (!STATUS_APPROVED.equals(a.status())) throw conflict("ALLOCATION_NOT_APPROVED", ...);
                WindowRow w = windows.get(p.allocationKey());
                long dayStart = dayStartNanos(p.date()); long dayEnd = dayStartNanos(p.date().plusDays(1));
                if (dayStart < w.startNanos() || dayEnd > w.endNanos()) throw 422 DATE_OUT_OF_WINDOW with detail;
                EvaporationRateRow rate = rates.get(channel + "@" + date);
                BigDecimal loss = p.delivered().multiply(rate.rate()).setScale(2, RoundingMode.HALF_EVEN);
                BigDecimal deducted = p.delivered().add(loss).setScale(2, RoundingMode.HALF_EVEN);
                if (deducted.subtract(loss).compareTo(p.delivered()) != 0) throw 422 CONSERVATION_VIOLATION detail;
                BigDecimal remain = running.get(key).subtract(deducted);
                if (remain.signum() < 0) throw 422 UPSTREAM_QUOTA_INSUFFICIENT with 实际/要求/差额;
                running.put(key, remain);
                computed.add(new Computed(p, w, rate, loss, deducted, remain));
