    public SettlementResponse reverseSettlement(String commandKey, String settlementKey, String reversalKey) {
        requireKey x3;
        String params = "SETTLEMENT_REVERSAL|" + settlementKey + "|" + reversalKey;
        return runCommand("SETTLEMENT_REVERSAL", commandKey, params, SettlementResponse.class, () -> {
            SettlementRow original = repository.findSettlementByKey(settlementKey);
            if (original == null) throw notFound("SETTLEMENT_NOT_FOUND", ...);
            if (!KIND_SETTLEMENT.equals(original.kind())) throw conflict("NOT_REVERSABLE", "反向更正记录不能再次被更正");
            if (repository.findSettlementByKey(reversalKey) != null) throw conflict("SETTLEMENT_KEY_REUSED", ...);
            AllocationRow allocation = repository.lockAllocationByKey(original.allocationKey());
            if (!STATUS_APPROVED.equals(allocation.status())) throw conflict("ALLOCATION_NOT_APPROVED", "只有 APPROVED 状态的申请可以回补额度");
            if (repository.findReversalOf(settlementKey) != null) throw conflict("ALREADY_REVERSED", "该核销已被反向更正: " + settlementKey);
            BigDecimal newHeld = allocation.heldAmount().add(original.deductedAmount());
            if (newHeld.compareTo(allocation.amount()) > 0) throw unprocessable("REVERSAL_EXCEEDS_QUOTA", ...);
            long now = nowNanos();
            repository.incrementHeldAmount(allocation.id(), original.deductedAmount(), now);
            repository.insertSettlement(reversalKey, KIND_REVERSAL, original.windowId(), original.allocationKey(),
                    original.channelId(), original.rateDate(), original.rateVersion(), original.rate(),
                    original.deliveredAmount().negate(), original.lossAmount().negate(),
                    original.deductedAmount().negate(), settlementKey, now);
            return toSettlementResponse(repository.findSettlementByKey(reversalKey), newHeld);
        });
    }
