    static LocalDate parseDate(String field, String value) {
        if (value == null || value.isBlank()) throw badRequest(field + " 不能为空");
        try { return LocalDate.parse(value.trim()); }
        catch (DateTimeParseException e) { throw badRequest(field + " 不是合法的 UTC 日期(yyyy-MM-dd): " + value); }
    }

    static BigDecimal parseRate(String value) {
        if null/blank → 400
        if (!RATE_PATTERN.matcher(trimmed).matches()) → 400 "rate 必须为 0~0.2 的十进制字符串，最多四位小数"
        BigDecimal rate = new BigDecimal(trimmed);
        if (rate.signum() < 0 || rate.compareTo(MAX_RATE) > 0) → 400 "rate 必须在 0~0.2 之间（0~20%）"
        return rate;
    }

    static long dayStartNanos(LocalDate date) {
        return toNanos(date.atStartOfDay(ZoneOffset.UTC).toInstant());
    }
